import { Text } from "react-native";
import { create } from "zustand";
import { NavigationRail } from "@nyc-tron/ui";

const useSelection = create<{selected: string; select: (id:string) => void}>(set => ({selected: "overview", select: selected => set({selected})}));
export default function Example() {
  const selected = useSelection(s => s.selected);
  const select = useSelection(s => s.select);
  const rail = <NavigationRail edge="left" items={[{id:"overview",label:"Overview"},{id:"details",label:"Details"}]} selectedId={selected} onSelectionChange={select} />;
  return rail;
}

