import * as React from "react";
import { WindowsNavigationHost } from "@nyc-tron/windows-fluent-fabric/navigation-host";
import { createWindowsNavigationBinding } from "@nyc-tron/windows-fluent-fabric/navigation-binding";

// Requires the real RNW 0.85 Fabric native host.
export default function Example() {
  const binding = React.useRef<ReturnType<typeof createWindowsNavigationBinding> | null>(null);
  if (!binding.current) {
    binding.current = createWindowsNavigationBinding();
    binding.current.transport.setDestinations([{id:"overview",label:"Overview"}], []);
    binding.current.transport.setSelectedId("overview");
  }
  React.useEffect(() => () => binding.current?.dispose(), []);
  return <WindowsNavigationHost binding={binding.current} style={{width:300,height:420}} />;
}

